// <autogenerated />
using Microsoft.AspNetCore.Components;
using Shared.DTO.Customer;
using System.Net.Http.Json;

namespace HandymanWorkshop.Client.Pages.Customer
{
    public partial class Create
    {
        CustomerDto customer { get; set; } = new CustomerDto();

        [Inject]
        protected NavigationManager? NavMan { get; set; }

        protected async Task AddCustomer()
        {
            var response = await Http.PostAsJsonAsync("api/Customers", customer);
            if (response.IsSuccessStatusCode)
            {
                NavMan.NavigateTo("/Customer");
            }
            else
            {
                Console.WriteLine($"Error >> {response.ReasonPhrase}");
            }

        }
    }
}
